import java.io.*;import java.awt.*;import java.awt.image.*;import java.util.Base64;import javax.imageio.ImageIO;import com.koios.client.arpg.*;import com.koios.client.graphic.*;import com.koios.client.cache.Decompressor;import com.koios.client.stream.StreamLoader;import com.koios.game.arpg.PassiveTree;
public class TutorialLayoutPreview {static String payload(String text)throws Exception{return Base64.getEncoder().encodeToString(text.getBytes("UTF-8"));}static void canvas(BufferedImage image){DrawingArea.initDrawingArea(image.getHeight(),image.getWidth(),((DataBufferInt)image.getRaster().getDataBuffer()).getData());}public static void main(String[] args)throws Exception{try(RandomAccessFile data=new RandomAccessFile("../koios-cache/main_file_cache.dat","r");RandomAccessFile index=new RandomAccessFile("../koios-cache/main_file_cache.idx0","r")){TextDrawingArea font=new TextDrawingArea(false,"p12_full",new StreamLoader(new Decompressor(data,index,1).decompress(1)));StringBuilder state=new StringBuilder("tree|1|false");for(PassiveTree.Node node:PassiveTree.NODES.values())state.append("\n").append(node.id).append("|").append(node.parent).append("|false|").append(node.name).append("|").append(node.description());PrototypePanel panel=new PrototypePanel();panel.accept(payload(state.toString()));BufferedImage world=new BufferedImage(512,334,BufferedImage.TYPE_INT_RGB);canvas(world);panel.draw(font,-1,-1);BufferedImage chat=new BufferedImage(519,165,BufferedImage.TYPE_INT_RGB);canvas(chat);DrawingArea.drawPixels(165,0,0,0x1A242D,519);MapObjective objective=new MapObjective();objective.accept(payload("TUTORIAL 3 / 10\nAllocate your first passive\nClick an available node in the passive tree."));objective.drawInChat(font,0);font.method389(true,12,0x8CA7BC,"Press Enter or click to chat",133);BufferedImage frame=new BufferedImage(519,503,BufferedImage.TYPE_INT_RGB);Graphics2D g=frame.createGraphics();g.drawImage(world,4,4,null);g.drawImage(chat,0,338,null);g.dispose();ImageIO.write(frame,"png",new File("build/tutorial-layout.png"));System.out.println("Rendered tutorial/tree layout with actual client font and renderer.");}}}
